Both `entries` and `embeddings` Maps are unbounded. A 384-dimension float64 embedding costs ~3KB, so 100K entries ≈ 300MB in embeddings alone. Add a max-capacity eviction:

```typescript
class VectorStore {
  private readonly maxEntries: number = 50_000;

  async store(entry: MemoryEntry): Promise<void> {
    if (this.entries.size >= this.maxEntries) {
      this.evictLRU(); // evict by oldest accessedAt
    }
    this.entries.set(entry.id, entry);
    if (entry.embedding) this.embeddings.set(entry.id, entry.embedding);
  }

  private evictLRU(): void {
    let oldest: MemoryEntry | undefined;
    for (const entry of this.entries.values()) {
      if (!oldest || entry.accessedAt < oldest.accessedAt) oldest = entry;
    }
    if (oldest) this.delete(oldest.id);
  }
}
```

