`getAncestors` does `for (const [source, targets] of this.adjacency)` plus `targets.includes(current)` per node — O(N × out-degree) per DFS step. Build a reverse adjacency at insertion time:

```typescript
class GraphEngine {
  private reverseAdjacency: Map<string, string[]> = new Map(); // target → sources

  addEdge(edge: CausalEdge): void {
    // existing forward adjacency...
    const rev = this.reverseAdjacency.get(edge.target) ?? [];
    rev.push(edge.source);
    this.reverseAdjacency.set(edge.target, rev);
  }

  getAncestors(nodeId: string, maxDepth = 3): string[] {
    const ancestors = new Set<string>();
    const dfs = (current: string, depth: number) => {
      if (depth >= maxDepth) return;
      for (const source of this.reverseAdjacency.get(current) ?? []) {
        if (!ancestors.has(source)) {
          ancestors.add(source);
          dfs(source, depth + 1);
        }
      }
    };
    dfs(nodeId, 0);
    return [...ancestors];
  }
}
```

